const items = $input.all();

const requiredFields = [
  "Date",
  "Department",
  "Category",
  "Budget_Amount",
  "Actual_Amount",
  "Manager"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {
  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  if (missingFields.length === 0) {
    validItems.push(data);
  } else {
    invalidItems.push({
      department: data.Department || "Unknown",
      category: data.Category || "Unknown",
      missing_fields: missingFields
    });
  }
}

return [
  {
    json: {
      data_valid: invalidItems.length === 0,
      total_records: items.length,
      valid_records: validItems.length,
      invalid_records: invalidItems.length,
      invalid_details: invalidItems,
      budget_data: validItems
    }
  }
];

const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("AI returned invalid JSON: " + result);
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const data = $json;

const records = data.category_analysis || [];

return records.map(record => ({
  json: {
    report_id: `BUDGET-${Date.now()}-${record.department}`,

    report_date: new Date().toISOString().split("T")[0],

    department: record.department,
    category: record.category,

    budget_amount: record.budget_amount,
    actual_amount: record.actual_amount,

    variance_amount: record.variance_amount,
    variance_percentage: record.variance_percentage,

    variance_status: record.variance_status,
    severity: record.severity,

    recommendation: record.recommended_action,
    reason: record.reason,

    overall_status: data.overall_status,

    created_at: new Date().toISOString()
  }
}));
